INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40396, 0, 0, 0, 0, 0, 0, 0, 0, 'I can\'t believe he didn\'t toss this away.$B$BIn my anger I might\'ve mistaken Cookie’s actions, he was always a scared catfish. He must\'ve panicked.$B$B<Grayson sighs for a moment>.$B$BDrying the book, keeping this necklace...$B$BOh $N, what have I done.', 0),
(41392, 0, 0, 0, 0, 0, 0, 0, 0, 'By the mines of Kezan! This smells horrible. One whiff of it and any grown sailor will fall over in a heartbeat. $N, excellent job. While we were able to secure this end of the operations, we still have to investigate where exactly they\'re getting all the supplies from, as I am sure the Venture Co. is simply a middle man. Still, so far you did great and for that I\'ve got a reward for you. Stay clear of trouble, adventurer, wouldn\'t want to see you getting killed.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40396, 0, 0, 'Is he done with?', 0),
(41392, 0, 0, 'Don\'t waste time. I\'m not as patient as Master Shaw.', 0);
